audit.command:
PYTHONDONTWRITEBYTECODE=1 python3 - <<'PY'
import ast, hashlib, json, pathlib, subprocess, re
root = pathlib.Path(".").resolve()
roots = {"core": root, "pro": root.parent / "orze-pro"}
path = root / "docs/evidence/2026-09-10-v1-05c2e1-controller-stop-refusal.json"
record = json.loads(path.read_text())
inventory = json.loads((root / record["inventory"]["path"]).read_text())
validation = json.loads((root / record["root_validation"]["path"]).read_text())
out = {"files": {}, "references": 0, "command_occurrences": 0, "python_heredocs": 0}
for repo, entries in inventory["final_files"].items():
    directory = roots[repo]
    expected_paths = {e["path"] for e in entries}
    current_paths = set(subprocess.check_output(["git", "-C", str(directory), "ls-files", "-c", "-o", "--exclude-standard", "-z", "--", "src", "tests", "pyproject.toml"]).decode().strip("\0").split("\0"))
    assert expected_paths == current_paths, (repo, "pathset")
    for entry in entries:
        raw = (directory / entry["path"]).read_bytes()
        assert hashlib.sha256(raw).hexdigest() == entry["sha256"], (repo, entry["path"], "worktree")
        fixed = subprocess.check_output(["git", "-C", str(directory), "show", record["code_commits"][repo] + ":" + entry["path"]])
        assert hashlib.sha256(fixed).hexdigest() == entry["sha256"], (repo, entry["path"], "fixed commit")
    subprocess.run(["git", "-C", str(directory), "merge-base", "--is-ancestor", record["code_commits"][repo], "HEAD"], check=True)
    out["files"][repo] = len(entries)
refs = [record["root_validation"], record["inventory"], *record["references"]]
documents = [record, validation]
for ref in refs:
    raw = (roots[ref.get("repo", "core")] / ref["path"]).read_bytes()
    assert hashlib.sha256(raw).hexdigest() == ref["sha256"], ref["path"]
    if ref["path"].endswith(".json"):
        documents.append(json.loads(raw))
    out["references"] += 1
def inspect(value, key=""):
    if isinstance(value, dict):
        for k, v in value.items():
            inspect(v, k)
    elif isinstance(value, list):
        for v in value:
            inspect(v, key)
    elif isinstance(value, str) and (key == "command" or key.endswith("_command") or key in ("core", "pro", "paired", "new_core", "new_pro")) and ("python3 " in value or value.startswith("git ")):
        subprocess.run(["bash", "-n"], input=value.encode(), check=True, capture_output=True)
        out["command_occurrences"] += 1
        for body in re.findall(r"<<'PY'\n(.*?)\nPY(?:\n|$)", value, flags=re.S):
            ast.parse(body)
            out["python_heredocs"] += 1
for document in documents:
    inspect(document)
checked = subprocess.run(["bash", "-c", validation["static_audit_command"]], cwd=root, text=True, capture_output=True)
assert checked.returncode == 0, checked.stderr
assert json.loads(checked.stdout) == validation["static_audit"]
out["static_audit_exact"] = True
assert inventory["final_pre_post_exact"] == {"core": True, "pro": True}
assert validation["final_epoch"]["all_exit_zero"] is True
print(json.dumps(out, sort_keys=True))
PY
